def remove_duplicates(rows: list[dict], key_fields: list[str] | None = None) -> list[dict]:
    seen = set()
    unique = []
    for row in rows:
        if key_fields:
            key = tuple((k, row.get(k)) for k in key_fields)
        else:
            key = tuple(sorted(row.items()))
        if key not in seen:
            seen.add(key)
            unique.append(row)
    return unique
